/** FX rates for settlement and display, backed by the vendor CLI with a per-run cache. */
public class RateService {
    /**
     * Vendor source that gives the settlement reference rate for a date the default source marks stale (~N).
     * Checked against partner statements with fxq 3.4.1 (matches all 10/01~10/05 lines); not valid for 2.8.
     */
    static final int SETTLEMENT_SRC = 3;

    private final FxqClient client;
    private final Map<String, FxQuote> cache = new HashMap<>();
    private int vendorCalls;

    public RateService(FxqClient client) {
        this.client = client;
    }

    public FxQuote quote(String currency, LocalDate date) {
        String pair = CurrencyPairs.pairOf(currency);
        return cache.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date));
        });
    }

    /** Rate applied to card transactions of the given KST settlement date. */
    public BigDecimal settlementRate(String currency, LocalDate date) {
        FxQuote q = quote(currency, date);
        if (!q.stale()) return q.rate();
        return settlementQuote(q.pair(), date).rate();
    }

    /** Re-quotes a stale date from the settlement source; a stale answer again is refused rather than applied. */
    private FxQuote settlementQuote(String pair, LocalDate date) {
        FxQuote q = cache.computeIfAbsent(pair + "@" + date + "@src" + SETTLEMENT_SRC, k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date, SETTLEMENT_SRC));
        });
        if (q.stale()) {
            throw new IllegalStateException("no settlement rate for " + pair + " " + date + ": still stale");
        }
        return q;
    }

